-- Sample rows for fims.budget_allocation (the Memo Request / CBA-RFA page), so the list, filters,
-- status badges and the "parent CBA" picker have something to show on a dev DB.
--
-- * Needs: fims.fiscal_year (2026), fims.program / sub_program (PROG-001 / SUBPROG-001..003),
--   fims.settings_status (status_for = 'budget_allocation'), fims.budget_category, fims.type_of_fund,
--   fims.responsibility_code and uac.users ('budget_officer'). Run it after those seeds.
-- * request_referrence_no (RR-001, ...) is generated by the column default — it is not set here.
-- * Guarded by allocation_number (WHERE NOT EXISTS), so re-running this file is a no-op.
-- * Delete the demo rows with:  DELETE FROM fims.budget_allocation WHERE allocation_number LIKE 'SAMPLE-%';
--   (children first: the RFA rows point at their CBA through parent_id).

-- ---------------------------------------------------------------------------
-- 0. Sample vendors (fims.vendors had no seed data), one per kind of allocation below:
--    contractor (infrastructure), supplier + service provider (goods and services), consultant.
--    Guarded by vendor_code. Remove with:  DELETE FROM fims.vendors WHERE vendor_code LIKE 'SAMPLE-VEND-%';
--    (after the allocations that reference them are deleted).
-- ---------------------------------------------------------------------------
INSERT INTO fims.vendors (vendor_code, vendor_name, vendor_type, tin, address, contact_person, contact_number,
                          email, bank_name, bank_account_number, tax_classification, is_vat_registered, status)
SELECT v.* FROM (VALUES
  ('SAMPLE-VEND-01', 'Pioneer Builders and Construction Corp.', 'CONTRACTOR', '004-512-338-00000',
   '120 Aurora Boulevard, Cubao, 1109 Quezon City, NCR', 'Engr. Ramon dela Cruz', '0917-555-0101',
   'bids@pioneerbuilders.example.com', 'Land Bank of the Philippines', '1234-5678-90', 'VAT', TRUE, 'ACTIVE'),
  ('SAMPLE-VEND-02', 'Metro Office Supplies Trading', 'SUPPLIER', '301-224-776-00000',
   '45 Kamias Road, Diliman, 1101 Quezon City, NCR', 'Maria Santos', '0928-555-0202',
   'sales@metrooffice.example.com', 'Development Bank of the Philippines', '9876-5432-10', 'NON-VAT', FALSE, 'ACTIVE'),
  ('SAMPLE-VEND-03', 'Jackson Auto Services', 'SERVICE_PROVIDER', '289-899-715-00000',
   '25 Central Avenue, Tandang Sora, 1116 Quezon City, NCR', 'Jackson Reyes', '0935-555-0303',
   'service@jacksonauto.example.com', 'BDO Unibank', '0011-2233-44', 'NON-VAT', FALSE, 'ACTIVE'),
  ('SAMPLE-VEND-04', 'Lumina Development Consultants', 'CONSULTANT', '215-908-442-00000',
   '8th Floor, Ayala Tower, Makati City, NCR', 'Dr. Elena Villanueva', '0945-555-0404',
   'info@luminaconsult.example.com', 'Land Bank of the Philippines', '5566-7788-99', 'VAT', TRUE, 'ACTIVE')
) AS v(vendor_code, vendor_name, vendor_type, tin, address, contact_person, contact_number, email, bank_name,
       bank_account_number, tax_classification, is_vat_registered, status)
WHERE NOT EXISTS (SELECT 1 FROM fims.vendors x WHERE x.vendor_code = v.vendor_code);

-- ---------------------------------------------------------------------------
-- 1. CBA rows (no parent). Lines live in line_transaction (jsonb).
-- ---------------------------------------------------------------------------
INSERT INTO fims.budget_allocation (
    allocation_type, allocation_number, fiscal_year, requesting_rc_id,
    program_code, sub_program_code, document_type, description,
    workflow_route, category_id, is_bidding, line_transaction, status_id, user_id
)
SELECT v.allocation_type, v.allocation_number, v.fiscal_year, v.rc_id,
       v.program_code, v.sub_program_code, v.document_type, v.description,
       v.workflow_route, (SELECT budget_category_id FROM fims.budget_category WHERE name = v.category LIMIT 1),
       v.is_bidding, v.lines::jsonb,
       (SELECT id FROM fims.settings_status WHERE name = v.status AND status_for = 'budget_allocation' LIMIT 1),
       (SELECT user_id FROM uac.users WHERE username = 'budget_officer' LIMIT 1)
FROM (VALUES
  ('CBA', 'SAMPLE-CBA-2026-01', 2026, '001', 'PROG-001', 'SUBPROG-001', 'CO',
   'Construction of Phase 1 housing units - site development',
   'Regular', 'Infrastructure', TRUE, 'Approved',
   '[{"type_of_fund":"CORPORATE RECEIPT","account_code":"1-06-05-030","account_title":"Buildings and Other Structures","fiscal_yr":"2026","proposed_amount":"25000000.00","requested_amount":"20000000.00","allocated_amount":"20000000.00"}]'),
  ('CBA', 'SAMPLE-CBA-2026-02', 2026, '006', 'PROG-001', 'SUBPROG-002', 'COE',
   'Office supplies, utilities and vehicle maintenance for the first semester',
   'Regular', 'Goods and Services', FALSE, 'Approved',
   '[{"type_of_fund":"CORPORATE RECEIPT","account_code":"5-02-03-990","account_title":"Other General Services","fiscal_yr":"2026","proposed_amount":"3500000.00","requested_amount":"3000000.00","allocated_amount":"3000000.00"},{"type_of_fund":"CORPORATE RECEIPT","account_code":"5-02-01","account_title":"Traveling Expenses","fiscal_yr":"2026","proposed_amount":"1200000.00","requested_amount":"1000000.00","allocated_amount":"1000000.00"}]'),
  ('CBA', 'SAMPLE-CBA-2026-03', 2026, '004', 'PROG-002', 'SUBPROG-003', 'COE',
   'Engagement of consultant for resettlement program evaluation',
   'Regular', 'Consultancy', FALSE, 'For Preview',
   '[{"type_of_fund":"NG SUPPORT - GAA","account_code":"5-02-03-990","account_title":"Other General Services","fiscal_yr":"2026","proposed_amount":"1500000.00","requested_amount":"1500000.00","allocated_amount":""}]'),
  ('CBA', NULL, 2026, '005', 'PROG-001', 'SUBPROG-001', 'COE',
   'Audit software licenses (draft, not yet submitted)',
   'Regular', 'Goods and Services', FALSE, 'Draft',
   '[{"type_of_fund":"TRUST FUND","account_code":"5-02-03-990","account_title":"Other General Services","fiscal_yr":"2026","proposed_amount":"800000.00","requested_amount":"750000.00","allocated_amount":""}]'),
  ('CBA', NULL, 2026, '001', 'PROG-002', 'SUBPROG-003', 'CO',
   'Land improvement works - returned for revision of the requested amount',
   'Regular', 'Infrastructure', TRUE, 'Returned',
   '[{"type_of_fund":"NG SUPPORT - UF","account_code":"1-06-05-030","account_title":"Buildings and Other Structures","fiscal_yr":"2026","proposed_amount":"9000000.00","requested_amount":"9000000.00","allocated_amount":""}]')
) AS v(allocation_type, allocation_number, fiscal_year, rc_id, program_code, sub_program_code, document_type,
       description, workflow_route, category, is_bidding, status, lines)
WHERE (v.allocation_number IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM fims.budget_allocation a WHERE a.allocation_number = v.allocation_number))
   OR (v.allocation_number IS NULL
        AND NOT EXISTS (SELECT 1 FROM fims.budget_allocation a WHERE a.description = v.description));

-- Drafts / returned requests have no number yet; give the sample ones a recognisable one so they can be cleaned up.
UPDATE fims.budget_allocation SET allocation_number = 'SAMPLE-DRAFT-' || allocation_id
WHERE allocation_number IS NULL AND description IN
      ('Audit software licenses (draft, not yet submitted)',
       'Land improvement works - returned for revision of the requested amount');

-- ---------------------------------------------------------------------------
-- 2. RFA rows derived from an approved CBA (parent_id), with their PR / PO amounts.
-- ---------------------------------------------------------------------------
INSERT INTO fims.budget_allocation (
    allocation_type, allocation_number, fiscal_year, requesting_rc_id,
    program_code, sub_program_code, parent_id, document_type, description,
    pr_number, pr_amount, po_number, po_amount, workflow_route, category_id,
    line_transaction, status_id, user_id
)
SELECT 'RFA', v.allocation_number, 2026, p.requesting_rc_id,
       p.program_code, p.sub_program_code, p.allocation_id, p.document_type, v.description,
       v.pr_number, v.pr_amount, v.po_number, v.po_amount, 'Regular', p.category_id,
       v.lines::jsonb,
       (SELECT id FROM fims.settings_status WHERE name = v.status AND status_for = 'budget_allocation' LIMIT 1),
       p.user_id
FROM (VALUES
  ('SAMPLE-RFA-2026-01', 'SAMPLE-CBA-2026-01', 'First tranche - site development works',
   'PR-2026-0101', 8000000.00, 'PO-2026-0101', 7850000.00, 'Approved',
   '[{"type_of_fund":"CORPORATE RECEIPT","account_code":"1-06-05-030","account_title":"Buildings and Other Structures","fiscal_yr":"2026","requested_amount":"8000000.00","allocated_amount":"8000000.00"}]'),
  ('SAMPLE-RFA-2026-02', 'SAMPLE-CBA-2026-02', 'Vehicle maintenance and utilities - Q1',
   'PR-2026-0102', 450000.00, NULL, NULL, 'For Preview',
   '[{"type_of_fund":"CORPORATE RECEIPT","account_code":"5-02-03-990","account_title":"Other General Services","fiscal_yr":"2026","requested_amount":"450000.00","allocated_amount":""}]'),
  -- RFAs that already have a PO: these are the POs the IAR module (Inspection and Acceptance Report) can pick.
  -- Its PO amount is the sum of requested_amount in line_transaction.
  ('SAMPLE-RFA-2026-03', 'SAMPLE-CBA-2026-02', 'Office supplies and equipment - delivered in batches',
   'PR-2026-0103', 1200000.00, 'PO-2026-0102', 1185000.00, 'Approved',
   '[{"type_of_fund":"CORPORATE RECEIPT","account_code":"5-02-03-990","account_title":"Other General Services","fiscal_yr":"2026","requested_amount":"1200000.00","allocated_amount":"1200000.00"}]'),
  ('SAMPLE-RFA-2026-04', 'SAMPLE-CBA-2026-03', 'Consultancy services - program evaluation',
   'PR-2026-0104', 1500000.00, 'PO-2026-0103', 1500000.00, 'Approved',
   '[{"type_of_fund":"NG SUPPORT - GAA","account_code":"5-02-03-990","account_title":"Other General Services","fiscal_yr":"2026","requested_amount":"900000.00","allocated_amount":"900000.00"},{"type_of_fund":"NG SUPPORT - GAA","account_code":"5-02-03-990","account_title":"Other General Services","fiscal_yr":"2026","requested_amount":"600000.00","allocated_amount":"600000.00"}]')
) AS v(allocation_number, parent_number, description, pr_number, pr_amount, po_number, po_amount, status, lines)
JOIN fims.budget_allocation p ON p.allocation_number = v.parent_number
WHERE NOT EXISTS (SELECT 1 FROM fims.budget_allocation a WHERE a.allocation_number = v.allocation_number);

-- ---------------------------------------------------------------------------
-- 3. Link the sample vendors to the allocations (a vendor is only set where a PR / PO / contract exists).
-- ---------------------------------------------------------------------------
UPDATE fims.budget_allocation a
SET vendor_id = (SELECT vendor_id FROM fims.vendors WHERE vendor_code = m.vendor_code)
FROM (VALUES
  ('SAMPLE-CBA-2026-01', 'SAMPLE-VEND-01'),
  ('SAMPLE-RFA-2026-01', 'SAMPLE-VEND-01'),
  ('SAMPLE-CBA-2026-02', 'SAMPLE-VEND-02'),
  ('SAMPLE-RFA-2026-02', 'SAMPLE-VEND-03'),
  ('SAMPLE-RFA-2026-03', 'SAMPLE-VEND-02'),
  ('SAMPLE-RFA-2026-04', 'SAMPLE-VEND-04'),
  ('SAMPLE-CBA-2026-03', 'SAMPLE-VEND-04')
) AS m(allocation_number, vendor_code)
WHERE a.allocation_number = m.allocation_number AND a.vendor_id IS NULL;
